import React, { useState } from 'react';
import {
  Alert,
  Button,
  Stack,
  Typography,
} from '@mui/material';
import useReadinessLocale from '../../hooks/useReadinessLocale';

export const COMPLIANCE_ORCHESTRATION_TIP_KEY = 'ci_compliance_orchestration_tip_dismissed';

const ComplianceOrchestrationOnboardingTip: React.FC = () => {
  const { strings } = useReadinessLocale();
  const [dismissed, setDismissed] = useState(() => {
    if (typeof window === 'undefined') {
      return true;
    }
    return window.localStorage.getItem(COMPLIANCE_ORCHESTRATION_TIP_KEY) === '1';
  });

  if (dismissed) {
    return null;
  }

  const dismiss = () => {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(COMPLIANCE_ORCHESTRATION_TIP_KEY, '1');
    }
    setDismissed(true);
  };

  return (
    <Alert
      severity="info"
      sx={{ mb: 2 }}
      action={(
        <Button color="inherit" size="small" onClick={dismiss}>
          {strings.orchestrationTipDismiss}
        </Button>
      )}
    >
      <Typography variant="subtitle2" fontWeight={700} gutterBottom>
        {strings.orchestrationTipTitle}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
        {strings.orchestrationTipSubtitle}
      </Typography>
      <Stack component="ol" spacing={0.25} sx={{ m: 0, pl: 2.25 }}>
        {strings.orchestrationTipSteps.map((step) => (
          <Typography key={step} component="li" variant="body2" color="text.secondary">
            {step}
          </Typography>
        ))}
      </Stack>
    </Alert>
  );
};

export default ComplianceOrchestrationOnboardingTip;
